(7676921, 1255059, 99263, '<td valign="top">I love it...congratz on the Yellow Ribbon. I feel the haziness in fact adds to the image and gives it a painterly feel...almost like a Pierneef, and offsets the cow and grass in the foreground nicely.<br/><br/><i>Message edited by author 2020-10-16 02:57:26.</i></td>', 'I love it...congratz on the Yellow Ribbon. I feel the haziness in fact adds to the image and gives it a painterly feel...almost like a Pierneef, and offsets the cow and grass in the foreground nicely.', '2020-10-16 03:53:01.000000', '2020-10-16 03:57:26.000000', 0),
(7676928, 1255001, 3306, '<td valign="top">Congrats on the well deserved Blue. The subtle colors accentuate the peaceful quiet of your scene. I almost imagine that that is a woman in a cloak with a child following behind her in the background!</td>', 'Congrats on the well deserved Blue. The subtle colors accentuate the peaceful quiet of your scene. I almost imagine that that is a woman in a cloak with a child following behind her in the background!', '2020-10-16 06:08:43.000000', NULL, 0),
